import { useState, useEffect } from "react";
import {
  Layout,
  Menu,
  Card,
  Table,
  Tag,
  Button,
  Form,
  Input,
  Select,
  Upload,
  message,
  Statistic,
  Row,
  Col,
  Avatar,
  Badge,
  Divider,
  Empty,
  Spin,
  Popover,
  List,
} from "antd";
import {
  UserOutlined,
  FileTextOutlined,
  LogoutOutlined,
  CheckCircleOutlined,
  ClockCircleOutlined,
  CloseCircleOutlined,
  BellOutlined,
  HomeOutlined,
  PlusOutlined,
  FileDoneOutlined,
  InboxOutlined,
} from "@ant-design/icons";
import { useNavigate } from "react-router-dom";
import {
  submitApplication,
  getMyApplications,
  uploadDocument,
  removeToken,
  // 🔹 THÊM CÁC HÀM GỌI API THẬT VÀO ĐÂY
  getUniversities,
  getMajors,
  getCombinations,
  getDashboardStats,
} from "../../services/api";
import styles from "./index.less";

const { Sider, Content, Header } = Layout;
const { Option } = Select;
const { Dragger } = Upload;

const LOAI_GIAY_TO = [
  { id: "CCCD", name: "Căn cước công dân" },
  { id: "HOC_BA", name: "Học bạ THPT" },
  { id: "GIAY_UU_TIEN", name: "Giấy tờ ưu tiên" },
  { id: "OTHER", name: "Khác" },
];

const DOI_TUONG = [
  { id: "NONE", name: "Không có ưu tiên" },
  { id: "KV1", name: "Ưu tiên 1 (Khu vực 1)" },
  { id: "KV2", name: "Ưu tiên 2 (Khu vực 2)" },
];

const STATUS: Record<string, { color: string; icon: any; label: string }> = {
  pending: { color: "warning", icon: <ClockCircleOutlined />, label: "Chờ duyệt" },
  PENDING: { color: "warning", icon: <ClockCircleOutlined />, label: "Chờ duyệt" },
  approved: { color: "success", icon: <CheckCircleOutlined />, label: "Đã duyệt" },
  APPROVED: { color: "success", icon: <CheckCircleOutlined />, label: "Đã duyệt" },
  rejected: { color: "error", icon: <CloseCircleOutlined />, label: "Từ chối" },
  REJECTED: { color: "error", icon: <CloseCircleOutlined />, label: "Từ chối" },
};

export default function DashboardPage() {
  const navigate = useNavigate();
  const [tab, setTab] = useState("overview");
  const [apps, setApps] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);
  const [submitLoading, setSubmitLoading] = useState(false);
  const [uploadedFiles, setUploadedFiles] = useState<any[]>([]);
  const [uploadLoading, setUploadLoading] = useState(false);
  const [form] = Form.useForm();

  // 🔹 1. CÁC STATE LƯU TRỮ DỮ LIỆU ĐỘNG TỪ DATABASE THẬT
  const [stats, setStats] = useState<any>({
    totalApplications: 0,
    pendingApplications: 0,
    approvedApplications: 0,
    rejectedApplications: 0,
  });
  const [universities, setUniversities] = useState<any[]>([]);
  const [majors, setMajors] = useState<any[]>([]);
  const [combinations, setCombinations] = useState<any[]>([]);

  const user = (() => {
    try {
      return JSON.parse(localStorage.getItem("user") || "{}");
    } catch {
      return {};
    }
  })();

  // Hàm lấy lịch sử nộp hồ sơ
  const fetchApps = async () => {
    setLoading(true);
    try {
      const res = await getMyApplications();
      if (res.status === "success") setApps(res.data || []);
      else setApps([]);
    } catch {
      setApps([]);
    } finally {
      setLoading(false);
    }
  };

  // 🔹 2. HÀM LẤY SỐ LIỆU THỐNG KÊ 4 Ô TỪ API DASHBOARD
  const fetchStats = async () => {
    try {
      const res = await getDashboardStats();
      if (res.status === "success") {
        setStats(res.data);
      }
    } catch (err) {
      console.error("Không lấy được thống kê hệ thống", err);
    }
  };

  // 🔹 3. HÀM LẤY DANH MỤC TRƯỜNG/NGÀNH/TỔ HỢP TỪ DB ĐỂ ĐỔ VÀO DROPDOWN SELECT
  const fetchEducationData = async () => {
    try {
      const [resUni, resMajor, resCombo] = await Promise.all([
        getUniversities(),
        getMajors(),
        getCombinations(),
      ]);
      setUniversities(Array.isArray(resUni) ? resUni : resUni?.data || []);
      setMajors(Array.isArray(resMajor) ? resMajor : resMajor?.data || []);
      setCombinations(Array.isArray(resCombo) ? resCombo : resCombo?.data || []);
    } catch (err) {
      console.error("Lỗi đồng bộ danh mục giáo dục", err);
    }
  };

  // Kích hoạt nạp dữ liệu động khi mở trang lên
  useEffect(() => {
    fetchApps();
    fetchStats();
    fetchEducationData();
  }, []);

  const handleUpload = async (file: File) => {
    setUploadLoading(true);
    try {
      const res = await uploadDocument(file);
      if (res.status === "success") {
        setUploadedFiles((prev) => [
          ...prev,
          {
            originalName: res.data.originalName,
            fileUrl: res.data.fileUrl,
            mimeType: file.type,
            fileSize: file.size,
            fileType: "OTHER",
          },
        ]);
        message.success(`Tải lên "${file.name}" thành công!`);
      } else {
        message.error(res.message || "Tải file thất bại.");
      }
    } catch {
      message.error("Lỗi kết nối.");
    } finally {
      setUploadLoading(false);
    }
    return false;
  };

  const handleSubmit = async (values: any) => {
    if (uploadedFiles.length === 0) {
      message.warning("Vui lòng tải lên ít nhất 1 minh chứng!");
      return;
    }
    setSubmitLoading(true);
    try {
      const totalScore =
        parseFloat(values.score1 || 0) +
        parseFloat(values.score2 || 0) +
        parseFloat(values.score3 || 0);

      const res = await submitApplication({
        universityId: values.university,
        majorId: values.major,
        combinationId: values.combination,
        roundId: values.priority,
        scoreSubject1: parseFloat(values.score1),
        scoreSubject2: parseFloat(values.score2),
        scoreSubject3: parseFloat(values.score3),
        totalScore: totalScore,
        priorityObject: values.priorityType || "NONE",
        priorityScore: 0,
        files: uploadedFiles,
      });

      if (res.status === "success") {
        message.success("Nộp hồ sơ thành công!");
        form.resetFields();
        setUploadedFiles([]);
        fetchApps();
        fetchStats(); // Làm mới luôn số liệu thống kê ở màn hình chính
        setTab("history");
      } else {
        message.error(res.message || "Nộp hồ sơ thất bại.");
      }
    } catch {
      message.error("Lỗi kết nối.");
    } finally {
      setSubmitLoading(false);
    }
  };

  const handleFileTypeChange = (index: number, newType: string) => {
    setUploadedFiles((prev) => {
      const updatedFiles = [...prev];
      updatedFiles[index].fileType = newType;
      return updatedFiles;
    });
  };

  // 🔹 4. ĐỊNH NGHĨA CỘT BẢNG: TỰ ĐỘNG MAP TÊN TRƯỜNG/NGÀNH TỪ ID DƯỚI DB LÊN
  const columns = [
    {
      title: "STT",
      width: 60,
      render: (_: any, __: any, i: number) => <span className={styles.muted}>{i + 1}</span>,
    },
    {
      title: "Trường",
      dataIndex: "university_id",
      render: (v: string) => {
        const item = universities.find((u) => u.id === v || u.code === v);
        return <span style={{ color: "#fff" }}>{item ? item.name : v || "---"}</span>;
      },
    },
    {
      title: "Ngành đăng ký",
      dataIndex: "major_id",
      render: (v: string) => {
        const item = majors.find((m) => m.id === v || m.code === v);
        return <strong style={{ color: "#fff" }}>{item ? item.name : v}</strong>;
      },
    },
    {
      title: "Ngày nộp",
      dataIndex: "createdAt",
      render: (v: string) => (
        <span className={styles.muted}>
          {v ? new Date(v).toLocaleDateString("vi-VN") : "---"}
        </span>
      ),
    },
    {
      title: "Trạng thái",
      dataIndex: "status",
      render: (s: string) => {
        const c = STATUS[s] || STATUS.PENDING;
        return (
          <Tag icon={c.icon} color={c.color}>
            {c.label}
          </Tag>
        );
      },
    },
    {
      title: "Hồ sơ",
      dataIndex: "application_files",
      render: (_: any, record: any) => {
        const files = record.application_files || record.applicationFiles;
        return files && files.length > 0 ? (
          <a
            href={`http://localhost:5000${files[0].file_url || files[0].fileUrl}`}
            target="_blank"
            rel="noreferrer"
            className={styles.link}
          >
            Xem ↗
          </a>
        ) : (
          <span className={styles.muted}>—</span>
        );
      },
    },
  ];

  const notificationContent = (
    <div style={{ width: 320, maxHeight: 400, overflowY: "auto" }}>
      {apps.length === 0 ? (
        <Empty description="Bạn chưa có thông báo nào" image={Empty.PRESENTED_IMAGE_SIMPLE} />
      ) : (
        <List
          itemLayout="horizontal"
          dataSource={apps}
          renderItem={(app) => {
            let statusText = "";
            let color = "";
            if (app.status === "APPROVED" || app.status === "approved") {
              statusText = "đã được duyệt thành công";
              color = "#4ade80";
            } else if (app.status === "REJECTED" || app.status === "rejected") {
              statusText = "đã bị từ chối";
              color = "#f87171";
            } else {
              statusText = "đang trong quá trình chờ duyệt";
              color = "#fbbf24";
            }

            return (
              <List.Item style={{ padding: "12px 16px", cursor: "pointer", borderBottom: "1px solid #f0f0f0" }}>
                <List.Item.Meta
                  avatar={<BellOutlined style={{ color, fontSize: 18, marginTop: 4 }} />}
                  title={<span style={{ fontSize: 14, fontWeight: 600, color: "#1f2937" }}>Cập nhật hồ sơ</span>}
                  description={
                    <span style={{ fontSize: 13, color: "#4b5563" }}>
                      Hồ sơ xét tuyển vào ngành <strong>{app.major_id || app.majorId}</strong> của bạn {statusText}.
                    </span>
                  }
                />
              </List.Item>
            );
          }}
        />
      )}
    </div>
  );

  return (
    <Layout className={styles.layout}>
      <Sider width={240} className={styles.sider}>
