                  { label: "Đã duyệt", val: stats.approvedApplications || 0, icon: <CheckCircleOutlined />, color: "#4ade80" },
                  { label: "Chờ duyệt", val: stats.pendingApplications || 0, icon: <ClockCircleOutlined />, color: "#fbbf24" },
